import json

# Generate 26x26 grid with verified patterns
grid = [[0]*26 for _ in range(26)]

# Color 5: col = r + 9, rows 0-16
for r in range(17):
    grid[r][r+9] = 5 if r+9 < 26 else 0

# Color 4: col = r - 2, rows 2-25
for r in range(2, 26):
    grid[r][r-2] = 4 if r-2 >= 0 else 0

# Color 3: cols [r-9, r-8] for all rows
for r in range(26):
    for c in [r-9, r-8]:
        if 0 <= c < 26:
            grid[r][c] = 3

# Submit
print(json.dumps({"action": "submit", "grid": grid}))

